INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13835$nota-0272$m13835$, $m13836$Exercise Physiology McArdle.pdf$m13836$, $m13837$608$m13837$, $m13838$Small declines in VO2max become noticeable at an altitude of 589 m (1932 ft). Thereafter, arterial desaturation decreases VO2max by 7 to 9% per 1000-m (3280-ft) altitude increase to 6300 m (20,700 ft), where aerobic capacity declines at a more rapid, nonlinear rate... For example, aerobic capacity at 4000 m (13,123 ft) averages 75% of the sea-level value. At 7000 m (22,965 ft), VO2max averages one half that at sea level.$m13838$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13839$nota-0272$m13839$, $m13840$Exercise Physiology McArdle.pdf$m13840$, $m13841$613$m13841$, $m13842$Even with acclimatization, VO2max decreases about 2% for every 300 m (984 ft) above 1500 m (4921 ft). A decrement in endurance-related performance parallels reduced aerobic capacity.$m13842$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13843$nota-0272$m13843$, $m13844$nota-0134$m13844$, $m13845$complementa$m13845$, $m13846$nota-0134 tratava o ajuste por altitude apenas como princípio conceitual sem fórmula pronta; esta nota fornece a fórmula quantitativa de queda de VO2max por altitude que faltava$m13846$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13847$nota-0273$m13847$, $m13848$Exercise Physiology McArdle.pdf$m13848$, $m13849$608$m13849$, $m13850$As a broad guideline, it takes about 2 wk to adapt to altitudes up to 2300 m (7545 ft). Thereafter, each 610-m (2000-ft) altitude increase requires an additional week to fully acclimatize up to 4600 m (15,091ft).$m13850$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13851$nota-0273$m13851$, $m13852$Exercise Physiology McArdle.pdf$m13852$, $m13853$600$m13853$, $m13854$Acclimatization adaptations dissipate within 2 or 3 wk after returning to sea level.$m13854$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13855$nota-0273$m13855$, $m13856$nota-0134$m13856$, $m13857$complementa$m13857$, $m13858$fornece o cronograma temporal de aclimatização que faltava à nota-0134, que tratava altitude apenas como fator de ajuste de desempenho pontual$m13858$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13859$nota-0273$m13859$, $m13860$nota-0272$m13860$, $m13861$complementa$m13861$, $m13862$esta nota trata do tempo necessário para reduzir o impacto quantificado na nota-0272$m13862$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13863$nota-0276$m13863$, $m13864$Exercise Physiology McArdle.pdf$m13864$, $m13865$609$m13865$, $m13866$Altitude exerts no adverse effect on events lasting less than 2 min. For longer-duration events, poorer performance occurs at higher elevations than at sea level. The threshold for decrements appears at about 1600 m (5250 ft) for events of 2 to 5 min, while only a 600- to 700-m (1970 to 2300 ft) altitude induces poorer performance in events longer than 20 min.$m13866$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13867$nota-0276$m13867$, $m13868$Exercise Physiology McArdle.pdf$m13868$, $m13869$611$m13869$, $m13870$At 4000 m (13,123 ft), the runners could train only at the intensity equivalent to 39% of sea-level VO2max compared with an intensity of 78% when training at sea level.$m13870$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13871$nota-0276$m13871$, $m13872$nota-0272$m13872$, $m13873$complementa$m13873$, $m13874$nota-0272 quantifica a queda de VO2max por altitude; esta nota especifica em que duração de esforço essa queda começa a se manifestar como perda de desempenho$m13874$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13875$nota-0278$m13875$, $m13876$Exercise Physiology McArdle.pdf$m13876$, $m13877$746$m13877$, $m13878$The final derivation, referred to as the Siri equation, computes percentage body fat as: Percentage body fat = (495 ÷ body density) - 450$m13878$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13879$nota-0278$m13879$, $m13880$Exercise Physiology McArdle.pdf$m13880$, $m13881$747$m13881$, $m13882$A lower FFM density in weight trainers than in controls, 1.089 versus 1.099 g·cm−3, explained this discrepancy... For them, incorrect assumptions underlying the Siri equation overestimated percentage body fat.$m13882$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13883$nota-0278$m13883$, $m13884$Exercise Physiology McArdle.pdf$m13884$, $m13885$747$m13885$, $m13886$Based on revised densities of the FFM (1.089 g·cm−3) and fat mass (0.9007 g·cm−3), a modified equation more accurately appraises resistance-trained white males: Percentage body fat = (521 ÷ body density) - 478$m13886$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13887$nota-0279$m13887$, $m13888$Exercise Physiology McArdle.pdf$m13888$, $m13889$754$m13889$, $m13890$For example, sweat-loss dehydration from prior physical activity or reduced glycogen reserves (and associated loss of glycogen-bound water) from an intense training session reduces body resistance (impedance) to electrical current flow. This overestimates FFM and underestimates percentage body fat.$m13890$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13891$nota-0279$m13891$, $m13892$Exercise Physiology McArdle.pdf$m13892$, $m13893$754$m13893$, $m13894$Hydration level affects the accuracy of BIA to incorrectly determine an individual's body fat content... voluntary fluid restriction decreases the impedance measure. This lowers the percentage body fat estimate; hyperhydration produces the opposite effect (higher body fat estimate).$m13894$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13895$nota-0279$m13895$, $m13896$Exercise Physiology McArdle.pdf$m13896$, $m13897$754$m13897$, $m13898$BIA tends to overpredict body fat in lean and athletic subjects and underpredict body fat in obese subjects.116,159 BIA often predicts body fat less accurately than do girths and skinfolds.$m13898$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13899$nota-0279$m13899$, $m13900$nota-0278$m13900$, $m13901$complementa$m13901$, $m13902$outro método de composição corporal (BIA) com limitação distinta da equação de Siri, ambos relevantes para interpretar %gordura de ciclistas$m13902$)
